#!/usr/bin/env node
// extract.js — Extract the loadable memory image of an ELF64 binary as
// 4-byte little-endian words, keyed by virtual address.
//
// Usage: node extract.js <elf-file> > out.json
//
// For each PT_LOAD segment the binary maps into memory, we read every
// aligned 4-byte word and emit { "<vaddr>": <little-endian uint32> }.
// Only bytes that actually exist in the file (p_filesz) are read; .bss
// (p_memsz > p_filesz) has no on-disk content, so it is not emitted.
"use strict";

const fs = require("fs");

const PT_LOAD = 1;

function die(msg) {
  process.stderr.write("extract.js: " + msg + "\n");
  process.exit(1);
}

function extract(path) {
  const buf = fs.readFileSync(path);

  // --- Validate ELF64 little-endian ---
  if (buf.length < 64 ||
      buf[0] !== 0x7f || buf[1] !== 0x45 || buf[2] !== 0x4c || buf[3] !== 0x46) {
    die("not an ELF file");
  }
  if (buf[4] !== 2) die("not ELF64 (need 64-bit)");
  if (buf[5] !== 1) die("not little-endian");

  // --- ELF header fields we need ---
  const e_phoff = Number(buf.readBigUInt64LE(0x20));
  const e_phentsize = buf.readUInt16LE(0x36);
  const e_phnum = buf.readUInt16LE(0x38);

  // --- Walk program headers, collect PT_LOAD segments ---
  const loads = [];
  for (let i = 0; i < e_phnum; i++) {
    const o = e_phoff + i * e_phentsize;
    const p_type = buf.readUInt32LE(o);
    if (p_type !== PT_LOAD) continue;
    const p_offset = Number(buf.readBigUInt64LE(o + 0x08));
    const p_vaddr = Number(buf.readBigUInt64LE(o + 0x10));
    const p_filesz = Number(buf.readBigUInt64LE(o + 0x20));
    loads.push({ p_offset, p_vaddr, p_filesz });
  }

  // --- Emit every file-backed 4-byte word, keyed by virtual address ---
  const out = {};
  for (const seg of loads) {
    const { p_offset, p_vaddr, p_filesz } = seg;
    // Only whole words that fit in the file-backed region.
    const nWords = Math.floor(p_filesz / 4);
    for (let i = 0; i < nWords; i++) {
      const foff = p_offset + i * 4;
      const va = p_vaddr + i * 4;
      out[va] = buf.readUInt32LE(foff);
    }
  }
  return out;
}

function main(argv) {
  if (argv.length < 1) die("usage: node extract.js <elf-file>");
  const out = extract(argv[0]);
  process.stdout.write(JSON.stringify(out) + "\n");
}

main(process.argv.slice(2));

